/**
 * Procedural surface textures, painted on canvases at load time. Everything
 * here is generated by code, so the textures belong to the project and need
 * no licence, no download and no image files (pattern shared with Ocean
 * Explorer's generated textures). Seeded, so every load looks the same.
 */
import * as THREE from 'three';

function rng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function canvas(w: number, h = w) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  return { c, g: c.getContext('2d')! };
}

function tex(c: HTMLCanvasElement, repeat: [number, number] = [1, 1], color = true) {
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repeat[0], repeat[1]);
  t.anisotropy = 4;
  if (color) t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/** Scatter of small dots in a range of shades — the base of most natural surfaces. */
function speckle(g: CanvasRenderingContext2D, w: number, h: number, n: number, colors: string[], size: [number, number], seed: number) {
  const r = rng(seed);
  for (let i = 0; i < n; i++) {
    g.fillStyle = colors[Math.floor(r() * colors.length)];
    const s = size[0] + r() * (size[1] - size[0]);
    g.globalAlpha = 0.35 + r() * 0.5;
    g.fillRect(r() * w, r() * h, s, s);
  }
  g.globalAlpha = 1;
}

export function grass(repeat: [number, number]) {
  const { c, g } = canvas(256);
  g.fillStyle = '#6f9e4f';
  g.fillRect(0, 0, 256, 256);
  // Soft patches of lighter and darker turf, drawn wrapped so the tile has no seams.
  const r = rng(11);
  for (let i = 0; i < 30; i++) {
    const rad = 30 + r() * 50;
    const tone = r() > 0.5 ? 'rgba(128,170,88,0.16)' : 'rgba(82,120,60,0.16)';
    const cx = r() * 256;
    const cy = r() * 256;
    for (const ox of [-256, 0, 256]) {
      for (const oy of [-256, 0, 256]) {
        const grd = g.createRadialGradient(cx + ox, cy + oy, 0, cx + ox, cy + oy, rad);
        grd.addColorStop(0, tone);
        grd.addColorStop(1, 'rgba(0,0,0,0)');
        g.fillStyle = grd;
        g.fillRect(cx + ox - rad, cy + oy - rad, rad * 2, rad * 2);
      }
    }
  }
  // Blades.
  for (let i = 0; i < 2600; i++) {
    const x = r() * 256;
    const y = r() * 256;
    g.strokeStyle = ['#64903f', '#79ab56', '#5a8640', '#82b45e'][Math.floor(r() * 4)];
    g.globalAlpha = 0.35;
    g.beginPath();
    g.moveTo(x, y);
    g.lineTo(x + (r() - 0.5) * 2, y - 2 - r() * 3);
    g.stroke();
  }
  g.globalAlpha = 1;
  return tex(c, repeat);
}

export function asphalt(repeat: [number, number], centerLine = false) {
  const { c, g } = canvas(256);
  g.fillStyle = '#4a4e55';
  g.fillRect(0, 0, 256, 256);
  speckle(g, 256, 256, 5000, ['#3c4046', '#5b6068', '#6b7078', '#33363b'], [1, 2], 21);
  if (centerLine) {
    // Dashed yellow centre line along the texture's u axis, plus white edge lines.
    g.fillStyle = '#e9c84a';
    for (let x = 0; x < 256; x += 64) g.fillRect(x + 8, 124, 36, 8);
    g.fillStyle = 'rgba(235,235,225,0.85)';
    g.fillRect(0, 10, 256, 4);
    g.fillRect(0, 242, 256, 4);
  }
  return tex(c, repeat);
}

export function concrete(repeat: [number, number], seams = true) {
  const { c, g } = canvas(256);
  g.fillStyle = '#b9b7b0';
  g.fillRect(0, 0, 256, 256);
  speckle(g, 256, 256, 3500, ['#a9a79f', '#c8c6bf', '#9c9a93'], [1, 2], 31);
  if (seams) {
    g.strokeStyle = 'rgba(90,88,84,0.55)';
    g.lineWidth = 2;
    g.strokeRect(1, 1, 254, 254);
  }
  return tex(c, repeat);
}

export function gravel(repeat: [number, number]) {
  const { c, g } = canvas(256);
  g.fillStyle = '#9a968c';
  g.fillRect(0, 0, 256, 256);
  speckle(g, 256, 256, 7000, ['#7d796f', '#b4b0a6', '#8b877c', '#c9c5bb', '#6c685f'], [1, 3], 41);
  return tex(c, repeat);
}

/** Horizontal clapboard siding in a given paint colour. */
export function siding(color: string, repeat: [number, number]) {
  const { c, g } = canvas(128);
  g.fillStyle = color;
  g.fillRect(0, 0, 128, 128);
  for (let y = 0; y < 128; y += 16) {
    const grd = g.createLinearGradient(0, y, 0, y + 16);
    grd.addColorStop(0, 'rgba(255,255,255,0.18)');
    grd.addColorStop(0.85, 'rgba(0,0,0,0.05)');
    grd.addColorStop(1, 'rgba(0,0,0,0.35)');
    g.fillStyle = grd;
    g.fillRect(0, y, 128, 16);
  }
  return tex(c, repeat);
}

export function shingles(color: string, repeat: [number, number]) {
  const { c, g } = canvas(128);
  g.fillStyle = color;
  g.fillRect(0, 0, 128, 128);
  const r = rng(51);
  for (let row = 0; row < 8; row++) {
    const y = row * 16;
    const off = row % 2 ? 8 : 0;
    for (let x = -16; x < 128; x += 16) {
      const k = 0.8 + r() * 0.35;
      g.fillStyle = `rgba(${Math.round(30 * k)},${Math.round(20 * k)},${Math.round(18 * k)},${0.15 + r() * 0.25})`;
      g.fillRect(x + off + 1, y + 1, 14, 14);
    }
    g.fillStyle = 'rgba(0,0,0,0.4)';
    g.fillRect(0, y + 14, 128, 2);
  }
  return tex(c, repeat);
}

export function brick(repeat: [number, number]) {
  const { c, g } = canvas(256);
  g.fillStyle = '#cfc6b6';
  g.fillRect(0, 0, 256, 256);
  const r = rng(61);
  for (let row = 0; row < 16; row++) {
    const y = row * 16;
    const off = row % 2 ? 16 : 0;
    for (let x = -32; x < 256; x += 32) {
      const k = 0.82 + r() * 0.3;
      g.fillStyle = `rgb(${Math.round(160 * k)},${Math.round(70 * k)},${Math.round(52 * k)})`;
      g.fillRect(x + off + 1, y + 1, 30, 14);
    }
  }
  return tex(c, repeat);
}

/** Corrugated metal cladding (plant hall, battery containers). */
export function corrugated(color: string, repeat: [number, number]) {
  const { c, g } = canvas(128);
  g.fillStyle = color;
  g.fillRect(0, 0, 128, 128);
  for (let x = 0; x < 128; x += 8) {
    const grd = g.createLinearGradient(x, 0, x + 8, 0);
    grd.addColorStop(0, 'rgba(255,255,255,0.22)');
    grd.addColorStop(0.5, 'rgba(0,0,0,0.0)');
    grd.addColorStop(1, 'rgba(0,0,0,0.25)');
    g.fillStyle = grd;
    g.fillRect(x, 0, 8, 128);
  }
  return tex(c, repeat);
}

/** Photovoltaic cells: a grid of dark-blue cells with thin silver busbars. */
export function solarCells() {
  const { c, g } = canvas(256);
  g.fillStyle = '#c9ced6';
  g.fillRect(0, 0, 256, 256);
  const cols = 6;
  const rows = 10;
  const cw = 256 / cols;
  const ch = 256 / rows;
  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      const grd = g.createLinearGradient(i * cw, j * ch, (i + 1) * cw, (j + 1) * ch);
      grd.addColorStop(0, '#1d3768');
      grd.addColorStop(1, '#13264a');
      g.fillStyle = grd;
      g.fillRect(i * cw + 2, j * ch + 2, cw - 4, ch - 4);
      g.fillStyle = 'rgba(200,210,225,0.35)';
      g.fillRect(i * cw + cw / 3, j * ch + 2, 1, ch - 4);
      g.fillRect(i * cw + (2 * cw) / 3, j * ch + 2, 1, ch - 4);
    }
  }
  return tex(c);
}

export function wood(repeat: [number, number]) {
  const { c, g } = canvas(64, 256);
  g.fillStyle = '#6b4c34';
  g.fillRect(0, 0, 64, 256);
  const r = rng(71);
  for (let i = 0; i < 60; i++) {
    g.strokeStyle = r() > 0.5 ? 'rgba(40,26,16,0.35)' : 'rgba(140,106,76,0.3)';
    g.lineWidth = 1 + r() * 2;
    const x = r() * 64;
    g.beginPath();
    g.moveTo(x, 0);
    g.bezierCurveTo(x + (r() - 0.5) * 6, 80, x + (r() - 0.5) * 6, 170, x, 256);
    g.stroke();
  }
  return tex(c, repeat);
}

/** Painted stack bands (red and white) for the power plant chimneys. */
export function stackBands() {
  const { c, g } = canvas(16, 128);
  g.fillStyle = '#d8d6d0';
  g.fillRect(0, 0, 16, 128);
  g.fillStyle = '#b8473c';
  g.fillRect(0, 0, 16, 16);
  g.fillRect(0, 32, 16, 16);
  return tex(c);
}

/** See-through chain-link fence (alpha). */
export function chainLink(repeat: [number, number]) {
  const { c, g } = canvas(64);
  g.clearRect(0, 0, 64, 64);
  g.strokeStyle = 'rgba(190,196,204,0.95)';
  g.lineWidth = 2;
  g.beginPath();
  g.moveTo(0, 32);
  g.lineTo(32, 0);
  g.lineTo(64, 32);
  g.lineTo(32, 64);
  g.closePath();
  g.moveTo(-32, 32);
  g.lineTo(0, 0);
  g.moveTo(64, 0);
  g.lineTo(96, 32);
  g.stroke();
  return tex(c, repeat);
}

/** Awning stripes for the shop. */
export function stripes(a: string, b: string) {
  const { c, g } = canvas(64, 16);
  for (let x = 0; x < 64; x += 16) {
    g.fillStyle = a;
    g.fillRect(x, 0, 8, 16);
    g.fillStyle = b;
    g.fillRect(x + 8, 0, 8, 16);
  }
  return tex(c, [4, 1]);
}

/** A painted sign with text. */
export function sign(text: string, bg: string, fg: string) {
  const { c, g } = canvas(512, 128);
  g.fillStyle = bg;
  g.fillRect(0, 0, 512, 128);
  g.strokeStyle = 'rgba(255,255,255,0.6)';
  g.lineWidth = 6;
  g.strokeRect(6, 6, 500, 116);
  g.fillStyle = fg;
  g.font = `bold ${text.length > 8 ? 50 : 64}px system-ui, sans-serif`;
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.fillText(text, 256, 68);
  const t = tex(c);
  t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping;
  return t;
}

/** Vertical sky gradient used as the scene background (day, or evening with a sunset glow). */
export function sky(evening: boolean) {
  const { c, g } = canvas(4, 512);
  const grd = g.createLinearGradient(0, 0, 0, 512);
  if (evening) {
    grd.addColorStop(0, '#0b1230');
    grd.addColorStop(0.45, '#2a2b5c');
    grd.addColorStop(0.7, '#7a4a6b');
    grd.addColorStop(0.86, '#e2834f');
    grd.addColorStop(1, '#f6b36b');
  } else {
    grd.addColorStop(0, '#3f8fd8');
    grd.addColorStop(0.55, '#86bfe9');
    grd.addColorStop(1, '#d9ecf6');
  }
  g.fillStyle = grd;
  g.fillRect(0, 0, 4, 512);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/** Soft round sprite: clouds, steam, lamp halos and pools of light. */
export function softDot(inner: string, outer = 'rgba(255,255,255,0)') {
  const { c, g } = canvas(128);
  const grd = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  grd.addColorStop(0, inner);
  grd.addColorStop(1, outer);
  g.fillStyle = grd;
  g.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/** A puffy cloud built from overlapping soft circles. */
export function cloud(seed: number) {
  const { c, g } = canvas(256, 128);
  const r = rng(seed);
  for (let i = 0; i < 14; i++) {
    const x = 40 + r() * 176;
    const y = 50 + r() * 40;
    const rad = 22 + r() * 30;
    const grd = g.createRadialGradient(x, y, 0, x, y, rad);
    grd.addColorStop(0, 'rgba(255,255,255,0.95)');
    grd.addColorStop(0.6, 'rgba(255,255,255,0.75)');
    grd.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = grd;
    g.fillRect(x - rad, y - rad, rad * 2, rad * 2);
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
